import{_ as r,a0 as i,w as p,s,I as l,x as t,a1 as n,A as g,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const R=JSON.parse('{"title":"离开 Google：五年以来 | LCTT x X-CMD","titleTemplate":false,"description":"离开 Google：五年以来 | LCTT (202009) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"离开 Google：五年以来 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"离开 Google：五年以来 | LCTT (202009) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202009/20200804 Leaving Google- Five Years On","title":"离开 Google：五年以来","tag":"202009","desc":""},"relativePath":"202009/20200804 Leaving Google- Five Years On.md","filePath":"[post].md"}'),G={name:"202009/20200804 Leaving Google- Five Years On.md"};function m(f,o,d,a,S,T){const e=i("Link");return p(),s("div",null,[o[38]||(o[38]=l("h1",{id:"离开-google-五年以来",tabindex:"-1"},[t("离开 Google：五年以来 "),l("a",{class:"header-anchor",href:"#离开-google-五年以来","aria-label":"Permalink to “离开 Google：五年以来”"},"​")],-1)),o[39]||(o[39]=l("p",null,[l("img",{src:"https://img.linux.net.cn/data/attachment/album/202009/14/231115kqsf6q25s25ms66m.jpg",alt:""})],-1)),l("p",null,[o[1]||(o[1]=t("大约五年前的今天，我上交了 Google 员工证，然后走出了悉尼 Google 办公室，开启了一段自谋职业的崭新生活。我认为我应该详述一下这个故事，因为我通过阅读 ",-1)),n(e,{href:"https://mtlynch.io/why-i-quit-google/"},{default:g(()=>[...o[0]||(o[0]=[t("Michael Lynch",-1)])]),_:1}),o[2]||(o[2]=t(" 的作品而收获颇丰。正如你所看到的，我仍然花费了几年时间才开始考虑写这篇文章，但是最终我告诉自己，倘若我不在五周年纪念日写它，我就永远也不会写了。",-1))]),o[40]||(o[40]=u("",13)),l("p",null,[o[5]||(o[5]=t("这一次我用来自 ",-1)),n(e,{href:"https://projecteuler.net"},{default:g(()=>[...o[3]||(o[3]=[t("Project Euler",-1)])]),_:1}),o[6]||(o[6]=t(" 和 ",-1)),n(e,{href:"https://codingcompetitions.withgoogle.com/codejam"},{default:g(()=>[...o[4]||(o[4]=[t("Google CodeJam",-1)])]),_:1}),o[7]||(o[7]=t(" 的题进行练习。电话面试过程中，我不得不在 Google Doc 上进行一些在线编程，这有点儿尴尬，但是除此以外电话面试一切顺利。然后我受邀前往六本木的 Mori Tower 办公室进行了为期一天的现场面试。",-1))]),o[41]||(o[41]=l("p",null,[l("img",{src:"https://theartofmachinery.com/images/leaving_google/mori-tower.jpg",alt:"Mori Tower in Tokyo, where I interviewed for Google. It's the sixth tallest building in the city, which means it's huge. Photo from here."})],-1)),o[42]||(o[42]=l("p",null,"我的首个面试非常糟糕。我的脑子僵住了。我知道我能够解出那些题目，但是直到面试官走出房间我才想出答案。我立刻就感到很放松，并且意识到这是一个三元搜索问题。这是在是很令人沮丧，但是我觉得继续前进，看看剩下的面试进展如何。",-1)),o[43]||(o[43]=l("p",null,"其中的两道面试题很糟糕。其中之一直至今日仍然是我遇到过的最糟糕的面试问题。面试官说：“你用同一输入运行一个程序两次，得到了两个不同的结果。告诉我这是为什么。”我回答道：“当这种情况在现代计算机上发生而且并不在我的预期之中时，通常是竞态条件。”他只说：“不，这不是竞态条件。”然后看着我等着我的下一个回答。如果他有兴趣讨论一下的话，这个问题本该是一个很棒的问题，但是很显然他实际上只想玩“猜猜神秘数”。对于我所说的几乎全部内容，他只是回答：“不。”显然，该程序完全是确定性的，不存储任何状态，并且不依赖于环境（例如磁盘或是实时时钟），但却在每次执行时都给出不同的结果。我怀疑我们对于“被存储的状态”或是“环境”的含义还是某些东西有着不同的理解，但是我无法区分。有一次（变得绝望了）我试着问电子元件的温度变化是否会有影响，而他说：“不，那会是一个竞态条件，我已经告诉过你这不是竞态条件了。”最终，面试结束了，而我仍然不知道那个秘密数字是什么。",-1)),o[44]||(o[44]=l("p",null,"我讲这个故事的原因是，我听说过许多更为平淡的恐怖故事，用以证明面试官是憎恶面试者的坏人。然而，与流行的刻板印象所相反的是，当天的大多数面试基本上都还可以，面试官也很友好并且很尊重人。面试也着实很困难，因此最好减少面试官的工作量。希望那个“猜数字”面试官从 Google HR 那里得到的反馈是，他的问题对于作出聘用决定没什么帮助。",-1)),o[45]||(o[45]=l("p",null,"这次，面试带来了一份要约，但是有一个小问题：这份工作在悉尼，担任站点可靠性工程师（SRE）。我以前从未听说过 SRE，但是我和一位悉尼的资深 SRE 通了电话，他解释说他注意到了我在天然气行业从事嵌入式工程的经历，并且认为 SRE 会和适合我，因为同样强调可靠性与拟合紧密约束。",-1)),l("p",null,[o[9]||(o[9]=t("在东京花了大约一年时间来建立起自己的生活，我不想抛弃一切然后搬到悉尼，但是我绝不可能会拒绝一份来自 Google 的要约。与招聘人员交谈时，我确实犯了一个非常愚蠢的错误：我被问到当时能赚多少钱，然后我就脱口而出。",-1)),n(e,{href:"https://www.kalzumeus.com/2012/01/23/salary-negotiation/"},{default:g(()=>[...o[8]||(o[8]=[t("别这么做",-1)])]),_:1}),o[10]||(o[10]=t("。这意味着不管在面试中发生了什么事情，或是你上一份工作中被底薪了多少，或者其它什么。你可能会被拒绝，或者会在原来的薪水基础上得到一些象征性的提升，并且如果你试图进一步协商，会被认为疯狂而又不合理。就我而言，我的收入甚至远远低于 Google 的入门级职位。我无法肯定地说全是这样，但是在 2013 年我搬到了悉尼，在 Google Maps 成为了一名新毕业生级别的 SRE。",-1))]),o[46]||(o[46]=l("h3",{id:"悉尼的-google-maps-sre",tabindex:"-1"},[t("悉尼的 Google Maps SRE "),l("a",{class:"header-anchor",href:"#悉尼的-google-maps-sre","aria-label":"Permalink to “悉尼的 Google Maps SRE”"},"​")],-1)),o[47]||(o[47]=l("p",null,"像 Maps 这样的产品实际上是若干个软件项目，每个都有自己的开发人员团队。甚至诸如路线查找之类的功能实际上也是多个软件项目 —— 从交通时刻表数据收集，到线路计算，再到结果渲染，等等等等。 SRE 的工作包含两个方面：一方面是为各个项目提供待命，实时响应任何生产事故；另一方面（在无需救火时）则是将生产事故中所积攒的经验应用到其他项目中去，并且发现其中可能出错的方式，或是发现使其性能更好的机会。Google 的 SRE 还需要像开发人员的内部咨询小组一样，对部署实践、自动化、监控或是类似的问题提供咨询。",-1)),o[48]||(o[48]=l("p",null,"这项工作相当紧张。作为一个团队，我们每周至少需要处理一次生产事故，否则就要为更多的服务提供支持。每个礼拜，悉尼的所有 SRE 都会聚在一起，交流发生过的故障事件或是有关如何使事情更好地运转的新技巧。学习曲线的感觉就像是再次成为了一名本科生。",-1)),o[49]||(o[49]=l("p",null,"我有时会感到震惊，听说我选择离开 Google 的人会问：“但是你不会想念那些福利吗？！”物质上的福利（例如伙食等等）绝对很棒，但是它们是你可以买到的东西，因此，不，它们不是我所想念的东西。如果你问我所想念的是什么，我会说是在那里工作的人们。与你可能听说过的不同，傲慢的人不喜欢在 Google 之类的地方工作。有一个臭名昭著的故事，一个自恋的人在 Google 找了份工作，并假装自己是各方面的顶级专家，让自己尴尬不已。他待了不到半年就离开了。总的来说，与我工作过的其他地方相比，这里的文化在傲慢、指责以及政治方面很少。另一方面，Google 并没有垄断好同事。",-1)),l("p",null,[o[12]||(o[12]=t("不过，有一种公司政治是个大问题。晋升需要“展示影响”，而众所周知的是，要做到这一点最简单的方法是发布一些新事物（不是惟一的方法，但是最简单）。结果是 Googler 们比起改进现有的解决方案，对于推广他们自己内测品质的原型方案更感兴趣。在 SRE 之间，我们经常开玩笑说， Google 内部有两种软件：一种是老的东西，工作得很好，但已经废弃了，甚至连考虑使用都是不够谷歌化的；另一种是热门的新东西，尽管它们还不能用，但却是今天 100% 可以使用的官方工具。作为 SRE，我们经常亲眼看到新的热点事物出了什么问题（有时甚至在没出 alpha 之前它就已经成了过时的旧东西）。（",-1)),n(e,{href:"https://theartofmachinery.com/2019/03/19/hello_world_marketing.html"},{default:g(()=>[...o[11]||(o[11]=[t("我此前已经对这类事物进行了更为深入的讨论。",-1)])]),_:1}),o[13]||(o[13]=t("）",-1))]),o[50]||(o[50]=l("p",null,"这不是我们这些愤世疾俗的 SRE 所想象的东西；这在公司中被公认为是一个问题，而我记得有人向我保证，晋升委员会已经开始通过维护工作等方式寻找关于其影响的证据。",-1)),o[51]||(o[51]=l("h3",{id:"晋升申请",tabindex:"-1"},[t("晋升申请 "),l("a",{class:"header-anchor",href:"#晋升申请","aria-label":"Permalink to “晋升申请”"},"​")],-1)),o[52]||(o[52]=l("p",null,"2015 年，在 Google 工作了两年之后，我的经理告诉我，现在是时候申请一个高于我新毕业生水准的晋升了。晋升过程是每年两次由晋升委员会进行集中管理的。你可以先提出申请，然后加上一份对你所从事过的项目的简短描述，再加上同事的推荐信。委员会将会进行审查，然后给你赞成或反对的意见。仅仅有你经理的推荐是不够的，因为你的经理有想让你获得晋升的动机。手下有高级别的员工有助于你自己的职业发展。",-1)),l("p",null,[o[15]||(o[15]=t("长话短说，我提交了我的申请，而委员会说不。事实上，这是个相当糟糕的拒绝。我不记得详细的答复了，但感觉就像是委员会在我的申请中寻找可以不屑一顾的东西。例如，我从事过的一个项目是一个内部工具，它出现了功能需求的积压。我查看了这个项目，发现根本问题在于它已经超出了构建它的键值存储，需要一个合适的数据库。我主张切换到关系数据库，并实现了它：模式、数据迁移、查询、实时站点迁移等等。新查询的速度要快得多，而且（更重要的是）可以有效地支持新功能。在进行迁移之前，我必须要解决的一个问题是大部分代码没有被测试所覆盖，而这是由于大部分的代码都不可测试。我使用依赖注入以及",-1)),n(e,{href:"https://theartofmachinery.com/2016/03/28/dirtying_pure_functions_can_be_useful.html"},{default:g(()=>[...o[14]||(o[14]=[t("我此前讨论过的其他技巧",-1)])]),_:1}),o[16]||(o[16]=t("重构了代码，而这使我能够构建一组回归测试套件。我记得这个项目被驳回主要是被评价为测试单元的编写是“新毕业生水平的工作”。",-1))]),o[53]||(o[53]=l("p",null,"我的经理真的很支持我，并且写了上诉。他没有给我看，但是我认为这是可以被缩减成 “WTF” 的若干页（更雄辩而详尽地论述）。以下是一些我也认为这一回复有点 “WTF” 的原因：",-1)),o[54]||(o[54]=l("p",null,"Google SRE 有一种“关键人物”的概念。一个项目的关键人物有两个角色：一个是比起其他 SRE 对于软件项目有着更为深入的了解，以便你能够回答他们可能会提出的问题；另一个角色是作为项目本身的开发人员的第一联络人，以便他们的所有 SRE 问题都能得到回答。 Google 的职业阶梯指南说，关键人物不应该处于“新毕业生水准”，而应该晋升。正如我在申请中所写的，我是三个项目的关键人物。",-1)),o[55]||(o[55]=l("p",null,"我的关键人物经历使得想要找到同意支持我的晋升申请的资深开发人员很容易。当他们发现我是新毕业生级别时都十分震惊。他们都同意支持我的申请，认可我已经处在了一个更高的级别。",-1)),o[56]||(o[56]=l("p",null,"在我的申请之中，我提到曾担任过一组新毕业实习生的导师。当我提出申请时，他们之中的许多人都已经被聘用为了正式雇员。我足够资深，可以去担任他们的导师，但是还绝不足以晋升到比他们更高的级别。",-1)),o[57]||(o[57]=l("p",null,"给我经理上诉的回复与最初的审查截然不同。这次，我“大大超出了对于我‘新毕业生’级别工作的期望”，但是问题在于他们需要稍多一些时间来确保我能够晋升到新毕业生加一的级别。我被告知在接下来的 6 个月时间里，倘若我能够继续超出预期，直到下一个晋升周期，也许那时我就会得到晋升。上诉结束了；这就是最终结果。",-1)),o[58]||(o[58]=l("p",null,"我写了一封电子邮件，表示我要采取另一种选择。就像许多科技公司一样， Google 也有员工持股计划。在开始工作时，你会得到一笔象征性的补助金，而在各个“投资”里程碑时刻，你会收到真正的股份。我的下一次股票授予是在几个月之后。从那以后，我将不再为 Google 工作。",-1)),o[59]||(o[59]=l("h3",{id:"我离开的原因",tabindex:"-1"},[t("我离开的原因 "),l("a",{class:"header-anchor",href:"#我离开的原因","aria-label":"Permalink to “我离开的原因”"},"​")],-1)),l("p",null,[o[18]||(o[18]=t("任何辞职的决定并不容易，而某天你或许会面临同样的抉择。以下是一些有助于我作出决定的因素。（",-1)),n(e,{href:"https://theartofmachinery.com/2018/10/07/payrise_by_switching_jobs.html"},{default:g(()=>[...o[17]||(o[17]=[t("我在以前的一篇贴子里对一些这类想法进行了更深入的解释。",-1)])]),_:1}),o[19]||(o[19]=t("）",-1))]),o[60]||(o[60]=l("p",null,"如果你思考一下，考虑到我并不是字面意义上真正的应届毕业生， Google 的评价应该是这样的：“你正在做一些非常错误的事情。在 X、 Y 还有 Z 方面有所改进之前，你根本不会得到晋升。”被告知“你远远超出了预期，但是我们还需要 6 个月左右的时间”，这是毫无道理的。没有人关注我是否有能力做好我的工作。我得到了许多借口，但是没有能够帮助我提高的任何有用反馈。（注意：有时候你必须要明确地要求反馈。经理们可能会陷入捍卫自己所给出的绩效评级的陷阱，而不会去考虑报告是否需要反馈。）",-1)),o[61]||(o[61]=l("p",null,"我也不确定晋升委员会会在 6 个月里看到什么他们在已经过去的 2 年时间里都没有看到的问题。他们难保不会再要求 6 个月时间？如果我需要花上多年时间来证明自己以获得新毕业生加一的级别晋升，那么我升到新毕业生加二的时候得有多老呢？",-1)),o[62]||(o[62]=l("p",null,"刚加入 Google 时，我的工作级别无关紧要，因为我当时学到了那么多东西，并且能在我的简历里写入一家著名的公司。两年过后，等式变得不同了。 Google 所提供给我的未来所具有的价值正在下降，而 Google 之外机会的价值却正在上升。 Google 的职位实际上在 Google 之外几乎毫无意义。在过去的 5 年间，许多人都问过我在 Google 做过什么，但是没有一个人问我在 Google 是什么职位，也没人称我为“新毕业生”。尽管我在短期内受到了财务方面的打击，但实际上在我上交员工证的那天我就已经得到了晋升。",-1)),o[63]||(o[63]=l("p",null,"值得称赞的是，Google 没有做过任何类似于以下的事情，但是在其他公司中却很常见：试图让员工对于要求加薪感到内疚。在几年前我工作过的地方，一些工程师在一次成功发布会后，在许多紧要关头要求加薪。管理层扮演起了受害者的角色，并且指责工程师们是在“强迫他们”。（大约 6 个月时间后，他们失去了自己大部分的工程团队。）如果你真的愿意就辞职时间进行配合（例如，在发布日期之后，而不是前一周），并且愿意记录下你的知识并做了整理等等，那么你仅仅是由于雇主支付给你的工资不足而“强迫他们”。",-1)),o[64]||(o[64]=l("p",null,"名义上，我在 Google 留下了大量未授予的股票。但是知道你拥有股票时，股票才属于你。我只是得到了未来会有分红的承诺，而我可以将其除以所需的时间来将其转换为同等的工资率。为这项投资工作 2 个月是值得的，为了剩余的投资工作数年是不值得的。不要被授予股票的偏见所迷惑。",-1)),o[65]||(o[65]=l("p",null,"什么时候不应该辞职呢？嗯，与在其他地方相比，你能得到的很多吗？公司的职业发展道路不是天上掉下来的，他们是一系列的业务报价，代表着你将为什么样的公司评估而工作。如果你认为自己能得到很多（考虑到所有的薪酬和像是工作环境之类的无形资产），很好！否则，是时候认真考虑一下下一步该做什么了。",-1)),o[66]||(o[66]=l("h3",{id:"离开-google-之后",tabindex:"-1"},[t("离开 Google 之后 "),l("a",{class:"header-anchor",href:"#离开-google-之后","aria-label":"Permalink to “离开 Google 之后”"},"​")],-1)),l("p",null,[o[21]||(o[21]=t("我应当警告你的是，我采取了高增长的战略，但是牺牲了短期稳定性。如果对你而言稳定性更为重要，你应该做出不一样的选择。我的 A 计划、 B 计划、 C 计划都失败了，我最终花费了几个月时间苦苦找寻出路。最后，我在一家小型网店得到了一份合同，为 ",-1)),n(e,{href:"https://www.safetytown.com.au/"},{default:g(()=>[...o[20]||(o[20]=[t("Safety Town",-1)])]),_:1}),o[22]||(o[22]=t(" 工作，一家政府建立的面向孩子们的道路安全网站。那里的薪水较之于 Google 是一个巨大的缩减，尤其是考虑到这是我几个月以来的第一份工作。但是，你知道，我真的很享受这个项目。当然了，它不像 Google 那么“酷”，而且可能一些学校里的孩子也不觉得它酷。另一方面，在 Google，我只是机器中的一个螺丝钉。 Safety Town 有一个小团队，每个人都扮演着至关重要的角色。在 Safety Town 项目中，我是后端工程师， Safety Town 当时是我唯一需要费心的事情。而且可能一些孩子已经在这个网站上学到了一两件有关道路安全的事情。从那以后，我做了很多项目，大多数都更大，但是我仍然会向人们展示 Safety Town。",-1))]),o[67]||(o[67]=l("p",null,[l("img",{src:"https://theartofmachinery.com/images/leaving_google/safetytown.png",alt:"Screenshot of Safety Town home page, owned by Australian NSW government."})],-1)),o[68]||(o[68]=l("p",null,"我记得 Google 悉尼办事处的一张海报，上面写着：“飞向月球吧！即使你错过了，你也会降落在群星之中！”人们很容易忘记，即使你不是在为知名公司或初创公司做“登月计划”，你也可以拥有高质量的生活。",-1)),o[69]||(o[69]=l("p",null,"这儿有一个帮助我获得合同的窍门。我会去参加悉尼的科技活动，站在能看到求职公告板的范围之中，等着看见有人在上面写东西。假设他们正在为一个保险公司项目写 CSS 开发方面的信息。即使我对 CSS 或保险不是特别感兴趣，我也会晃悠过去说：“嗨，这是个什么类型的保险项目？”这是最容易的开启谈话的方式，因为在他们努力往求职公告板上的狭小缝隙中写字的时候，满脑子都是这个项目。通常情况下，这样的谈话仍然不会为我带来一份工作，但是偶尔也会发现一些我能够帮上忙的东西。有些活动没有求职公告板，但是组织者们往往很乐意把麦克风递给别人几分钟。这为他们的活动增添了社区参与度。",-1)),o[70]||(o[70]=l("p",null,"我在做了一个政府采购的网站后，我取得了重大的突破，因为我学会了不至于对政府采购一窍不通。很难确切说出这些知识的价值，但是不到一年过后，我就签署了一份政府合同，比我此前所期望的要多了 40%。（不过，我如今没有做那么多的政府和大型企业的工作了。）",-1)),o[71]||(o[71]=l("p",null,"大约一年半过后，我有了自己的一人公司。随着我声誉的建立，我逐渐获得了更多类似于 SRE 的工作。基本上，从事开发工作是我的“工作”，然后几个月后就有一个需要 SRE/DevOps 帮助的人联系了我。我事实上既喜欢 SRE，也喜欢纯开发工作，但是供求关系意味着 SRE 工作是个好工作。我仍然可以在空余时间编程。",-1)),o[72]||(o[72]=l("p",null,"说起这个，工作与生活的平衡是我在新生活中最喜欢的事情。没有人在两份合同之间给我酬劳，但是我可以通过在业余项目中学习新东西来充分利用这一间隙。在一个漫长而又紧张的合同之后，我休息了一下，[进行了为期一个月的背包徒步旅行，探索了日本乡村][11]。这是我期待了很长时间的一次旅行，但是在入职 Google 之前我需要更多的钱，而在 Google 供职期间我又需要更多的时间。自营职业远非没有压力，也不是适合每一个人的，但是有的压力会让你感到死气沉沉，有的压力则会让你越发充满活力。于我而言，自主营生是第二种，我想说，和在 Google 时相比，过去的 5 年间我的压力总体上有所减轻。对于我来说，至少我能够诚实地说我不后悔当初加入 Google，也不后悔当初离开 Google。",-1)),o[73]||(o[73]=l("hr",null,null,-1)),l("p",null,[o[24]||(o[24]=t("via: ",-1)),n(e,{href:"https://theartofmachinery.com/2020/08/04/leaving_google.html"},{default:g(()=>[...o[23]||(o[23]=[t("https://theartofmachinery.com/2020/08/04/leaving_google.html",-1)])]),_:1})]),l("p",null,[o[29]||(o[29]=t("作者：",-1)),n(e,{href:"https://theartofmachinery.com"},{default:g(()=>[...o[25]||(o[25]=[t("Simon Arneaud",-1)])]),_:1}),o[30]||(o[30]=t(" 选题：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:g(()=>[...o[26]||(o[26]=[t("lujun9972",-1)])]),_:1}),o[31]||(o[31]=t(" 译者：",-1)),n(e,{href:"https://github.com/JonnieWayy"},{default:g(()=>[...o[27]||(o[27]=[t("JonnieWayy",-1)])]),_:1}),o[32]||(o[32]=t(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:g(()=>[...o[28]||(o[28]=[t("wxy",-1)])]),_:1})]),l("p",null,[o[35]||(o[35]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:g(()=>[...o[33]||(o[33]=[t("LCTT",-1)])]),_:1}),o[36]||(o[36]=t(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:g(()=>[...o[34]||(o[34]=[t("Linux中国",-1)])]),_:1}),o[37]||(o[37]=t(" 荣誉推出",-1))])])}const b=r(G,[["render",m]]);export{R as __pageData,b as default};
